UPDATE "MP_IPMS_PA".utb_board_mst
SET
    del_yn    = 'Y',
    update_at = NOW()
WHERE board_seq  = #{boardSeq}
  AND office_seq = #{officeSeq}

UPDATE "MP_IPMS_PA".utb_board_mst
SET view_count = view_count + 1
WHERE board_seq  = #{boardSeq}
  AND office_seq = #{officeSeq}
  AND del_yn     = 'N'

UPDATE "MP_IPMS_PA".utb_board_config_mst
SET
    parent_seq = #{parentSeq}
    ,board_type = #{boardType}
    ,board_name = #{boardName}
    ,description = #{description}
    ,share_scope = #{shareScope}
    ,admin_write_only_yn = #{adminWriteOnlyYn}
    ,notice_auth_type = #{noticeAuthType}
    ,new_post_alert_yn = #{newPostAlertYn}
    ,use_reaction_yn = #{useReactionYn}
    ,prefix_tags = #{prefixTags}
    ,view_type = #{viewType}
    ,status = #{status}
    ,disp_ord = #{dispOrd}
    ,update_user = #{updateUser}
    ,update_at = NOW()
WHERE config_seq = #{configSeq}
  AND office_seq = #{officeSeq}

UPDATE "MP_IPMS_PA".utb_board_config_mst
SET disp_ord = #{dispOrd}
    ,parent_seq = #{parentSeq, jdbcType=VARCHAR}
    ,update_user = #{updateUser}
    ,update_at = NOW()
WHERE config_seq = #{configSeq}
  AND office_seq = #{officeSeq}

UPDATE "MP_IPMS_PA".utb_board_config_mst
SET del_yn = 'Y'
    ,update_user = #{updateUser}
    ,update_at = NOW()
WHERE config_seq = #{configSeq}
  AND office_seq = #{officeSeq}

UPDATE "MP_IPMS_PA".utb_board_backup_hist
SET
    status = #{status}
    ,file_path = #{filePath}
    ,file_size = #{fileSize}
    ,file_name = #{fileName}
    ,file_seq = #{fileSeq}
    ,update_user = #{updateUser}
    ,update_at = NOW()
WHERE backup_seq = #{backupSeq}

UPDATE utb_board_backup_hist
SET del_yn = 'Y'
    ,update_user = #{updateUser}
    ,update_at = NOW()
WHERE backup_seq = #{backupSeq}

mapper.insert:
INSERT INTO "MP_IPMS_PA".utb_board_system_config (
    office_seq
    ,max_file_size
    ,max_body_size
    ,trash_retention_days
    ,allow_master_change_yn
    ,main_layout_type
    ,recent_post_count
    ,new_badge_duration
    ,show_pin_on_top_yn
    ,create_user
    ,create_at
) VALUES (
    #{officeSeq}
    ,#{maxFileSize}
    ,#{maxBodySize}
    ,#{trashRetentionDays}
    ,#{allowMasterChangeYn}
    ,#{mainLayoutType}
    ,#{recentPostCount}
    ,#{newBadgeDuration}
    ,#{showPinOnTopYn}
    ,#{createUser}
    ,NOW()
)
ON CONFLICT (office_seq) DO UPDATE SET
    max_file_size = EXCLUDED.max_file_size
    ,max_body_size = EXCLUDED.max_body_size
    ,trash_retention_days = EXCLUDED.trash_retention_days
    ,allow_master_change_yn = EXCLUDED.allow_master_change_yn
    ,main_layout_type = EXCLUDED.main_layout_type
    ,recent_post_count = EXCLUDED.recent_post_count
    ,new_badge_duration = EXCLUDED.new_badge_duration
    ,show_pin_on_top_yn = EXCLUDED.show_pin_on_top_yn
    ,update_user = #{updateUser}
    ,update_at = NOW()

