SELECT COUNT(*)
FROM "MP_IPMS_PA".utb_board_mst
WHERE office_seq = #{officeSeq}
  AND del_yn = 'N'

  AND config_seq = #{configSeq}

  AND create_at < NOW() - CAST(#{days} || ' days' AS INTERVAL)

