INSERT INTO "MP_IPMS_PA".utb_comment (
    comment_seq
    ,parent_comment_seq
    ,comment_type
    ,comment_content
    ,comment_code
    ,del_yn
    ,create_user
    ,create_at
) VALUES (
    #{commentSeq}
    ,#{parentCommentSeq, jdbcType=VARCHAR}
    ,#{commentType, jdbcType=VARCHAR}
    ,#{commentContent}
    ,#{commentCode, jdbcType=VARCHAR}
    ,'N'
    ,#{createUser}
    ,NOW()
)

