UPDATE "MP_IPMS_PA".utb_comment
SET
    comment_content = #{commentContent}
    ,comment_type   = #{commentType, jdbcType=VARCHAR}
    ,comment_code   = #{commentCode, jdbcType=VARCHAR}
    ,update_user    = #{updateUser}
    ,update_at      = NOW()
WHERE comment_seq = #{commentSeq}
  AND del_yn = 'N'

UPDATE "MP_IPMS_PA".utb_comment
SET
    del_yn      = 'Y'
    ,update_user = #{updateUser}
    ,update_at   = NOW()
WHERE comment_seq = #{commentSeq}

UPDATE "MP_IPMS_PA".utb_comment_mapp
